//! Login orchestration contract: shells supply I/O; ordering and failures are testable here.
use serde::Serialize;
use std::{future::Future, pin::Pin};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Stage { Register, Discover, Relay, Connect }

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Progress {
    pub stage: Stage,
    pub state: &'static str,
    pub error: Option<String>,
    pub retryable: bool,
}

pub trait Steps {
    fn execute(&mut self, stage: Stage)
        -> Pin<Box<dyn Future<Output = Result<(), String>> + Send + '_>>;
    fn publish(&mut self, progress: &Progress);
}

/// No detached success: return the exact failed stage, and never execute later stages.
/// A shell may retry from Discover after durable enrollment has succeeded.
pub async fn run(steps: &mut impl Steps, start: Stage) -> Progress {
    let stages = [Stage::Register, Stage::Discover, Stage::Relay, Stage::Connect];
    for stage in stages.into_iter().skip_while(|stage| *stage != start) {
        let mut progress = Progress { stage, state: "running", error: None, retryable: false };
        steps.publish(&progress);
        if let Err(error) = steps.execute(stage).await {
            progress.state = "failed";
            progress.error = Some(error);
            progress.retryable = true;
            steps.publish(&progress);
            return progress;
        }
    }
    let progress = Progress {
        stage: Stage::Connect, state: "ready", error: None, retryable: false,
    };
    steps.publish(&progress);
    progress
}

#[cfg(test)]
mod tests {
    use super::*;

    struct Fake { calls: Vec<Stage>, fail: Option<Stage>, published: Vec<Progress> }
    impl Steps for Fake {
        fn execute(&mut self, stage: Stage)
            -> Pin<Box<dyn Future<Output = Result<(), String>> + Send + '_>> {
            Box::pin(async move {
                self.calls.push(stage);
                if self.fail == Some(stage) { Err("injected failure".into()) } else { Ok(()) }
            })
        }
        fn publish(&mut self, progress: &Progress) { self.published.push(progress.clone()); }
    }

    #[tokio::test]
    async fn every_failure_stops_before_later_side_effects() {
        let stages = [Stage::Register, Stage::Discover, Stage::Relay, Stage::Connect];
        for (index, stage) in stages.into_iter().enumerate() {
            let mut fake = Fake { calls: vec![], fail: Some(stage), published: vec![] };
            let out = run(&mut fake, Stage::Register).await;
            assert_eq!(fake.calls, stages[..=index]);
            assert_eq!(out.stage, stage);
            assert_eq!(out.state, "failed");
            assert_eq!(out.error.as_deref(), Some("injected failure"));
            assert!(out.retryable);
        }
    }

    #[tokio::test]
    async fn retry_after_enrollment_does_not_rotate_device_key_again() {
        let mut fake = Fake { calls: vec![], fail: Some(Stage::Relay), published: vec![] };
        run(&mut fake, Stage::Register).await;
        fake.calls.clear();
        fake.fail = None;
        let out = run(&mut fake, Stage::Discover).await;
        assert_eq!(fake.calls, [Stage::Discover, Stage::Relay, Stage::Connect]);
        assert_eq!(out.state, "ready");
        assert!(!out.retryable);
    }
}
//! Shared post-login sequence and resumable background reconciliation.
use super::*;
use crate::collab::interconnect::login::{self as pipeline, Progress, Stage, Steps};
use std::{future::Future, pin::Pin};

static PROGRESS: parking_lot::Mutex<Option<Progress>> = parking_lot::Mutex::new(None);
static SERIAL: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());

pub(super) fn status() -> Value { json!(*PROGRESS.lock()) }

pub(super) fn relay_status() -> Value {
    #[cfg(feature = "collab-net")]
    { crate::collab::tunnel::relay_status() }
    #[cfg(not(feature = "collab-net"))]
    { json!({"state": "unavailable", "pending": false}) }
}

struct Enrollment {
    url: String,
    node: String,
    assertion: String,
    invite: String,
    console: bool,
}

#[derive(Default)]
struct Coordinator {
    enrollment: Option<Enrollment>,
    output: Value,
    response: Value,
    count: usize,
}

impl Steps for Coordinator {
    fn publish(&mut self, progress: &Progress) {
        *PROGRESS.lock() = Some(progress.clone());
        #[cfg(feature = "desktop")]
        crate::hosting::bus_emit("interconnect:progress", json!(progress));
    }

    fn execute(&mut self, stage: Stage)
        -> Pin<Box<dyn Future<Output = Result<(), String>> + Send + '_>> {
        Box::pin(async move {
            match stage {
                Stage::Register => {
                    let enrollment = self.enrollment.take().ok_or("缺登录凭据，请重新登录")?;
                    self.output = tokio::task::spawn_blocking(move || {
                        let out = super::login::enroll_with_assertion(
                            &enrollment.url, &enrollment.node, &enrollment.assertion,
                            &enrollment.invite, enrollment.console,
                        )?;
                        super::login::finish_enroll(&enrollment.url, &enrollment.node, &out)
                    }).await.map_err(|e| format!("登记设备任务失败: {e}"))??;
                }
                Stage::Discover => {
                    let config = cfg().ok_or("本机还没入网")?;
                    self.response = tokio::task::spawn_blocking(move || {
                        heal_local_membership(&config);
                        if !crate::collab::authority::is_member(&meta(K_UID)) {
                            return Err("本机成员资格未建立，无法互联".into());
                        }
                        announce(&config)
                    }).await.map_err(|e| format!("拉取设备清单任务失败: {e}"))??;
                }
                Stage::Relay => {
                    crate::collab::interconnect::apply_received_relays(&self.response)?;
                }
                Stage::Connect => {
                    let config = cfg().ok_or("本机还没入网")?;
                    let peers = self.response.get("peers").and_then(Value::as_array)
                        .ok_or("权威响应缺少 peers 数组")?;
                    self.count = reconcile_peers(&config, peers).await?;
                    let failures: Vec<String> = links().lock().map_err(|e| e.to_string())?
                        .values().filter(|link| !link.err.is_empty() || link.phase != "ready")
                        .map(|link| format!("{}: {} {}", link.name, link.phase, link.err)).collect();
                    if !failures.is_empty() { return Err(failures.join("; ")); }
                }
            }
            Ok(())
        })
    }
}

pub(super) async fn complete_login(
    url: String, node: String, assertion: String, invite: String, console: bool,
) -> Result<Value, String> {
    let _serial = SERIAL.lock().await;
    let mut coordinator = Coordinator {
        enrollment: Some(Enrollment { url, node, assertion, invite, console }),
        ..Coordinator::default()
    };
    let progress = pipeline::run(&mut coordinator, Stage::Register).await;
    if progress.stage == Stage::Register && progress.state == "failed" {
        return Err(progress.error.map_or_else(|| "登记设备失败".into(), |error| error));
    }
    // Enrollment has been persisted. Connectivity errors stay explicit and retry in the loop.
    spawn_loop();
    coordinator.output["interconnect"] = json!(progress);
    coordinator.output["relayConfig"] = relay_status();
    Ok(coordinator.output)
}

pub(super) async fn retry() -> Result<usize, String> {
    let _serial = SERIAL.lock().await;
    let mut coordinator = Coordinator::default();
    let progress = pipeline::run(&mut coordinator, Stage::Discover).await;
    if let Some(error) = progress.error { return Err(error); }
    Ok(coordinator.count)
}
//! Account discovery and login responses (including authority relay URLs).
use super::*;

/// 账号体系自述(公开):告诉客户端「本机的账号该在哪儿登」。
/// 三种回答对应三种部署:authority(我就是权威)/ delegated(去这个 URL 登)/ local(老行为,就地登)。
pub(super) async fn account_info() -> Response {
    let out = tokio::task::spawn_blocking(|| -> Result<Value, String> {
        use crate::collab::authority::{self, Mode};
        crate::collab::interconnect::load()?;
        // emailRequired 恒 false:邮箱是**可选**的(绑了才有自助找回)。
        // emailCapable 告诉前端「这儿发得出验证码吗」—— 发不出就别让人填邮箱空等。
        Ok(match authority::mode() {
            Mode::Authority => json!({
                "mode": "authority",
                "kid": authority::kid().unwrap_or_default(),
                "emailRequired": false,
                "emailCapable": crate::collab::mail::configured(),
                // 前端据此决定「注册」入口亮不亮:关着还亮就是骗用户填一遍再报 403。
                "signupOpen": std::env::var("POLARIS_ACCOUNT_OPEN_SIGNUP")
                    .map(|s| s == "1" || s.eq_ignore_ascii_case("true"))
                    .unwrap_or(false),
            }),
            Mode::Delegated(url) => {
                let pin = authority::pinned();
                json!({
                    "mode": "delegated",
                    "authorityUrl": url,
                    "trusted": pin.is_some(),
                    "kid": pin.map(|(_, _, k)| k).unwrap_or_default(),
                    "emailRequired": false,
                })
            }
            Mode::Local => json!({"mode": "local", "emailRequired": false}),
        })
    })
    .await;
    unwrap_api(out)
}

/// 权威公钥(公开):成员主机首次接触时钉住这一串。
pub(super) async fn account_pubkey() -> Response {
    if !crate::collab::authority::is_authority() {
        return not_authority();
    }
    let out = tokio::task::spawn_blocking(|| -> Result<Value, String> {
        let pk = crate::collab::authority::public_key_b64()?;
        Ok(json!({"fingerprint": crate::collab::interconnect::fingerprint(&pk)?,
            "publicKey": pk, "kid": crate::collab::authority::kid_of(&pk), "alg": "ed25519"}))
    })
    .await;
    unwrap_api(out)
}

/// 全局注册。邮箱**可选**:
///  · 不填邮箱 → 直接建号(没有自助找回,忘了密码得找管理员重置)。
///  · 填了邮箱 → 必须同时给出发到该邮箱的验证码,验过才绑 —— 绑一个没验证过的邮箱
///    等于把「找回密码」的钥匙交给一个不确定属于谁的地址,比不绑还危险。
///
/// **默认关闭自助注册**(须显式 `POLARIS_ACCOUNT_OPEN_SIGNUP=1` 才开)。
/// 原因:账号中心的 `users` 表同时就是这台机器自己的成员表 —— 放开自助注册,
/// 等于任何人都能拿到本机的 collaborator 会话,而成员能建项目、触发 checks 跑构建脚本,
/// 本质是主机 RCE。这与 `collab_signup` 默认邀请制是同一条理由,不能因为「它是账号中心」就松口。
/// 关闭时建号走服务端的 `seed_authority_account` 工具(要能读写权威库,不是远程口子)。
pub(super) async fn account_signup(Json(v): Json<Value>) -> Response {
    if !crate::collab::authority::is_authority() {
        return not_authority();
    }
    if !open_signup() {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({"error":"本账号中心未开放自助注册,请联系管理员开通账号"})),
        )
            .into_response();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let email = s_of(&v, "email");
        if !email.trim().is_empty() {
            if !crate::collab::mail::configured() {
                return Err("本账号中心没配邮件服务,发不出验证码 —— 请留空邮箱直接注册".into());
            }
            crate::collab::mail::verify_code(&email, "signup", &s_of(&v, "code"))?;
        }
        let username = s_of(&v, "username");
        let display = {
            let d = s_of(&v, "displayName");
            if d.trim().is_empty() {
                username.clone()
            } else {
                d
            }
        };
        let (u, uid) = crate::collab::auth::create_authority_account(
            &username,
            &s_of(&v, "password"),
            &display,
            &email,
        )?;
        let assertion =
            crate::collab::authority::sign_assertion(&uid, &u.username, &email, &display)?;
        Ok(json!({"user": u, "uid": uid, "email": email, "assertion": assertion,
            "relays": crate::collab::interconnect::advertised_relays()?}))
    })
    .await;
    unwrap_api(out)
}

/// 全局登录:用户名**或邮箱** + 密码 → 身份断言。权威只回答「你是谁」,
/// 不回答「你在某台主机上能干什么」—— 那是各主机自己的账。
pub(super) async fn account_login(Json(v): Json<Value>) -> Response {
    if !crate::collab::authority::is_authority() {
        return not_authority();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let ident = {
            let u = s_of(&v, "username");
            if u.trim().is_empty() {
                s_of(&v, "email")
            } else {
                u
            }
        };
        let (u, uid, email) = crate::collab::auth::authority_login(&ident, &s_of(&v, "password"))?;
        let assertion =
            crate::collab::authority::sign_assertion(&uid, &u.username, &email, &u.display_name)?;
        Ok(json!({
            "user": {"username": u.username, "displayName": u.display_name, "email": email},
            "uid": uid,
            "assertion": assertion,
            "relays": crate::collab::interconnect::advertised_relays()?,
        }))
    })
    .await;
    unwrap_api(out)
}

/// 全局验证码登录(账号权威):邮箱 + 验证码 → 身份断言,拿着它能进任意一台成员主机。
/// 与 `/api/account/login` 的区别只在于「凭什么证明是你」——那个用密码,这个用邮箱验证码。
///
/// **首登即注册**:这个邮箱还没有账号时当场建一个(受 `POLARIS_ACCOUNT_OPEN_SIGNUP` 闸控)。
/// 注册页因此可以整个消失 —— 用户从没填过用户名、没设过密码,只证明了「这个邮箱是我的」。
/// 建出来的账号密码位是哨兵串,永远不可能凭密码进来。
pub(super) async fn account_login_code(Json(v): Json<Value>) -> Response {
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        // 与 send_code 同一口径:成员主机当管子,把验证码原样递给账号中心、把断言原样带回来。
        // 主机自己不看、不改、不留 —— 它本来就没有能力验这枚码。
        if !crate::collab::authority::is_authority() {
            return crate::collab::authority::upstream_forward("/api/account/login_code", &v);
        }
        let email = s_of(&v, "email");
        // 验证码必须**先**过:否则「首登自动建号」就成了任何人往任意邮箱建号的口子。
        crate::collab::mail::verify_code(&email, "login", &s_of(&v, "code"))?;
        let (u, uid, email) = match crate::collab::auth::authority_identity_by_email(&email) {
            Ok(v) => v,
            Err(e) => {
                // 只有「没这个账号」才走自动建号;停用、缺 uid 这些要原样报出去,
                // 否则会绕过管理员的停用决定,凭空再造一个能用的号。
                if !e.contains("没有绑定任何账号") {
                    return Err(e);
                }
                if !open_signup() {
                    return Err("本账号中心未开放自助注册,请联系管理员开通账号".into());
                }
                match crate::collab::auth::create_account_by_verified_email(&email) {
                    Ok((u, uid)) => {
                        let e2 = crate::collab::auth::validate_email(&email)?;
                        (u, uid, e2)
                    }
                    // 并发首登:两台设备同时拿着同一枚码进来,一个建成、一个撞唯一索引。
                    // 撞了的那个直接读既有账号即可 —— 用户看到的是两台都登进去了。
                    Err(_) => crate::collab::auth::authority_identity_by_email(&email)?,
                }
            }
        };
        let assertion =
            crate::collab::authority::sign_assertion(&uid, &u.username, &email, &u.display_name)?;
        Ok(json!({
            "user": {"username": u.username, "displayName": u.display_name, "email": email},
            "uid": uid,
            "assertion": assertion,
            "relays": crate::collab::interconnect::advertised_relays()?,
        }))
    })
    .await;
    unwrap_api(out)
}

import { ref } from 'vue';
import { errMsg } from '../../lib/err';
import { interconnectCopy as c } from './copy';
import type { Command, Progress, RelayConfig } from './contracts';

export interface LoginResult {
  enrolled?: boolean; token?: string; interconnect?: Progress; relayConfig?: RelayConfig;
  authorityConfigured?: boolean; configurationError?: string;
}
export function useLogin(command: Command, adopt: (token: string) => Promise<void>, slowMs: number) {
  const progress = ref<Progress | null>(null);
  const relay = ref<RelayConfig>();
  const error = ref('');
  const busy = ref(false);
  const enrolled = ref(false);
  const authorityConfigured = ref<boolean>();
  let pollBusy = false;
  let disposed = false;
  function receive(result: LoginResult) {
    if (disposed) return;
    if (result.interconnect) progress.value = result.interconnect;
    if (result.relayConfig) relay.value = result.relayConfig;
    if (result.enrolled !== undefined) enrolled.value = result.enrolled;
    if (result.authorityConfigured !== undefined) authorityConfigured.value = result.authorityConfigured;
    if (result.configurationError) error.value = result.configurationError;
  }
  async function refresh() {
    if (pollBusy || disposed) return;
    pollBusy = true;
    try { receive(await command<LoginResult>('mesh_status')); }
    catch (e) { if (!disposed) error.value = errMsg(e); }
    finally { pollBusy = false; }
  }
  async function done(result: LoginResult) {
    receive(result);
    if (result.token) await adopt(result.token);
  }
  async function execute(action: () => Promise<LoginResult>) {
    if (busy.value || disposed) return;
    busy.value = true;
    error.value = '';
    const timer = setTimeout(() => { if (!disposed) error.value = c.timeout; }, slowMs);
    try {
      const result = await action();
      if (!disposed) error.value = '';
      await done(result);
    }
    catch (e) {
      if (!disposed) {
        error.value = errMsg(e);
        if (progress.value?.state !== 'failed') progress.value = null;
      }
    }
    finally { clearTimeout(timer); busy.value = false; }
  }
  async function login(username: string, password: string) {
    progress.value = null;
    await execute(async () => {
      await command('collab_host_start');
      return command<LoginResult>('account_login_password', { username, password });
    });
  }
  async function retry() {
    if (!enrolled.value || progress.value?.stage === 'register') return;
    await execute(() => command<LoginResult>('mesh_sync'));
    await refresh();
  }
  function dispose() { disposed = true; }
  return { progress, relay, error, busy, enrolled, authorityConfigured, receive, refresh, done, login, retry, dispose };
}
import { onMounted, onUnmounted, watch, ref } from 'vue';
import { invoke as rawInvoke, isTauri, listen } from '../../tauri';
import { useCollabStore } from '../collab/stores/collab';
import { useAccountStore } from '../../stores/account';
import { useLogin, type LoginResult } from './useLogin';
import { useSecurity } from './useSecurity';
import { timing, type Approval, type Device, type Notice, type Progress, type Timing } from './contracts';
import { interconnectCopy as c } from './copy';
import { errMsg } from '../../lib/err';

const riskCommands = new Set(['peer_grant_set', 'peer_trust', 'peer_revoke', 'mesh_device_remove',
  'mesh_kick', 'mesh_leave', 'fs_unmount', 'fs_share_save', 'fs_share_set']);
export function useInterconnect(
  collab: ReturnType<typeof useCollabStore>, account: ReturnType<typeof useAccountStore>,
  changed: () => Promise<void>, options: Partial<Timing> = {},
) {
  const config = timing(options);
  const login = useLogin(rawInvoke, async token => {
    await collab.adoptLocalSession(token);
    await account.refresh();
    await changed();
  }, config.slowMs);
  const security = useSecurity(rawInvoke);
  const ports = ref<Record<string, number>>({});
  const stops: (() => void)[] = [];
  let disposed = false;
  let poll: ReturnType<typeof setInterval>;
  let retry: ReturnType<typeof setInterval>;
  let polling = false;
  async function refresh() {
    if (!isTauri || polling || disposed) return;
    polling = true;
    try {
      await login.refresh();
      if (collab.authed && login.enrolled.value) {
        await security.refresh();
        const state = await rawInvoke<{ peers?: { nodeId: string; port: number }[] }>('mesh_status');
        if (!disposed) ports.value = Object.fromEntries((state.peers || []).map(p => [p.nodeId, p.port]));
      }
    } catch (e) { if (!disposed) login.error.value = errMsg(e); }
    finally { polling = false; }
  }
  async function passwordLogin(username: string, password: string) {
    if (isTauri) await login.login(username, password);
    else {
      login.busy.value = true;
      login.error.value = '';
      try { await collab.login(username, password); await account.refresh(); }
      catch (e) { login.error.value = errMsg(e); }
      finally { login.busy.value = false; }
    }
    await refresh();
  }
  async function emailDone(info: Record<string, unknown>) {
    await login.done(info as LoginResult);
    await changed();
    await refresh();
  }
  async function logout() {
    await security.run(async () => {
      // Gate before account.logout, which otherwise clears the session even when mesh_leave is pending.
      if (isTauri) await rawInvoke('mesh_leave');
      await collab.logout();
      await account.refresh();
      login.enrolled.value = false;
      login.progress.value = null;
      await changed();
    });
  }
  async function invoke<T>(name: string, args?: Record<string, unknown>): Promise<T> {
    if (!riskCommands.has(name)) return rawInvoke<T>(name, args);
    const payload = args ? JSON.parse(JSON.stringify(args)) as Record<string, unknown> : undefined;
    let result: T | undefined;
    let completed = false;
    await security.run(async () => {
      result = await rawInvoke<T>(name, payload);
      if ((result as { partial?: boolean })?.partial) throw new Error(c.partial);
      completed = true;
      void changed().catch(e => { login.error.value = errMsg(e); });
    });
    if (!completed) throw new Error(security.pending.value ? c.waiting : security.error.value);
    return result as T;
  }
  async function revokeNotice(notice: Notice) {
    const nodeId = notice.nodeId;
    const deviceId = notice.deviceId;
    await security.run(async () => {
      const result = await rawInvoke<{ partial?: boolean }>('mesh_device_remove', { nodeId });
      if (result.partial) throw new Error(c.partial);
      if (!await security.ack(deviceId)) throw new Error(security.error.value);
      await changed();
    });
  }
  async function subscribe<T>(name: string, callback: (event: T) => void) {
    try {
      const stop = await listen<T>(name, callback);
      if (disposed) stop(); else stops.push(stop);
    } catch (e) { if (!disposed) login.error.value = errMsg(e); }
  }
  watch(() => collab.authed, authed => { if (authed) void refresh(); else security.reset(); });
  onMounted(() => {
    if (isTauri) {
      void subscribe<Progress>('interconnect:progress', progress => login.receive({ interconnect: progress }));
      void subscribe<Notice | Approval>('interconnect:security', event => {
        if (!disposed && collab.authed) security.receive(event);
      });
      void refresh();
      poll = setInterval(() => void refresh(), config.pollMs);
      retry = setInterval(() => void security.tick(), config.retryMs);
    }
  });
  onUnmounted(() => {
    disposed = true;
    login.dispose();
    security.reset();
    stops.forEach(stop => stop());
    clearInterval(poll);
    clearInterval(retry);
  });
  function withPorts(devices: Device[]) {
    return devices.filter(d => !d.revoked).map(d => ({ ...d, port: ports.value[d.nodeId] }));
  }
  return { login, security, passwordLogin, emailDone, logout, invoke, revokeNotice, withPorts };
}

