/// 裸码和 `PLRS1-…` 分享码都收 —— 归一在 `authority::normalize_invite`。
///
/// 云端 enroll 或最终落库失败会直接保留在登录界面并允许重试；不会再保存一份缺 UID、
/// authority pin 或本机成员资格的“已入网”半成品。已经安全建立的本机 pin/成员关系可幂等复用。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn account_login_code(
    email: String,
    code: String,
    url: Option<String>,
    inviteCode: Option<String>,
    allowInsecureHttp: Option<bool>,
) -> Result<Value, String> {
    let url = validate_authority_url(&authority_of(url)?, allowInsecureHttp.unwrap_or(false))?;
    // NodeId 由本机密钥推导,不需要隧道在跑 —— 老版本那句「请先设为主机」其实是误导:
    // 真正需要主机在跑的是「别人连得进来」,不是「我拿得到身份」。所以这里不再拦人,
    // 拿不到才报错(那是密钥文件写不进去,是真问题)。
    let node_id = my_node_id();
    if node_id.is_empty() {
        return Err("本机 P2P 身份生成失败(数据目录写不进去?)—— 换个数据目录再试".into());
    }
    let invite = inviteCode.unwrap_or_default();
    let out = tokio::task::spawn_blocking({
        let url = url.clone();
        move || -> Result<Value, String> {
            crate::collab::authority::pin_explicit(&url)?;
            // ① 验证码 → 身份断言(账号不存在则当场建号,由账号中心决定)。
            let resp = agent()
                .post(&format!("{url}/api/account/login_code"))
                .send_json(json!({ "email": email.trim(), "code": code.trim() }))
                .map_err(cloud_err)?;
            let v: Value = resp
                .into_json()
                .map_err(|e| format!("账号中心返回的不是 JSON:{e}"))?;
            crate::collab::interconnect::apply_received_relays(&v)?;
            let assertion = v
                .get("assertion")
                .and_then(|x| x.as_str())
                .ok_or("账号中心没返回身份断言 —— 确认这个地址开了 POLARIS_ACCOUNT_AUTHORITY=1")?
                .to_string();
            let email_back = v
                .get("user")
                .and_then(|u| u.get("email"))
                .and_then(|x| x.as_str())
                .unwrap_or("")
                .to_string();
            Ok(json!({"assertion": assertion, "email": email_back}))
        }
    })
    .await
    .map_err(|e| format!("登录任务失败:{e}"))??;

    let assertion = out["assertion"].as_str().ok_or("登录响应缺断言")?.to_string();
    let email = out["email"].clone();
    let mut result = orchestration::complete_login(url, node_id, assertion, invite, true).await?;
    result["email"] = email;
    Ok(result)
}

/// 已有一张断言时的入网 + 进本机门。`account_login_code` 与 `mesh_join` 共用这一段,
/// 免得两条路各写一份、慢慢漂成两个语义。**阻塞**,调用方须放 spawn_blocking。
///
/// `console`=用户就坐在这台机器前亲手登的(桌面 App)。它决定第 ④ 步走哪一档准入:
/// 控制台可以认领这台机器上原有的那个账号(见 `Admission::LocalConsole`),远程递进来的
/// 断言不行。`invite` 是最后的兜底:这台机器已经有**别人**当主人时才用得上。
pub(super) fn enroll_with_assertion(
    url: &str,
    node_id: &str,
    assertion: &str,
    invite: &str,
    console: bool,
) -> Result<Value, String> {
    // ② 先钉账号中心。若本机已经信任另一套 authority，必须在取得长期 meshKey 之前
    // fail closed；否则会落出“云端已入网、别的设备永远进不来”的半成品。
    crate::collab::authority::pin_explicit(url)
        .map_err(|e| format!("账号中心信任未建立，尚未入网：{e}"))?;

    // ③ 再让当前账号进本机的门。邀请码兜底也必须在 enroll 前完成；本地准入失败时
    // 用户仍停留在登录界面，可以补设备码重试，而不是拿到 meshKey 后被假成功页藏住。
    let first = if console {
        crate::collab::authority::login_with_assertion_local(assertion, node_id)
    } else {
        crate::collab::authority::login_with_assertion(assertion, node_id)
    };
    let (user, token) = match first {
        Ok(v) => v,
        Err(e) if crate::collab::authority::normalize_invite(invite).is_empty() => {
            return Err(format!("本机成员准入未完成，尚未入网：{e}"));
        }
        Err(_) => {
            crate::collab::authority::join_with_ticket(assertion, invite, &my_name(), node_id)
                .map_err(|e| format!("本机成员准入未完成，尚未入网：{e}"))?
        }
    };

    // ④ 本地两道前置闸均通过后，才去云端换长期设备密钥。
    let resp = agent()
        .post(&format!("{url}/api/mesh/enroll"))
        .send_json(json!({
            "assertion": assertion,
            "nodeId": node_id,
            "name": my_name(),
            "os": my_os(),
            "ver": my_ver(),
        }))
        .map_err(cloud_err)?;
    let v: Value = resp
        .into_json()
        .map_err(|e| format!("账号中心返回的不是 JSON:{e}"))?;
    crate::collab::interconnect::apply_received_relays(&v)?;
    let key = v
        .get("meshKey")
        .and_then(|x| x.as_str())
        .ok_or("账号中心没返回设备密钥")?
        .to_string();
    let bound_assertion = fresh_assertion(&Cfg { url: url.into(), key: key.clone() })?;
    let (_, bound_token) = if console {
        crate::collab::authority::login_with_assertion_local(&bound_assertion, node_id)?
    } else {
        crate::collab::authority::login_with_assertion(&bound_assertion, node_id)?
    };
    crate::collab::auth::logout(&token)?;
    let token = bound_token;
    let uid = v
        .get("uid")
        .and_then(|x| x.as_str())
        .unwrap_or("")
        .to_string();

    Ok(json!({
        "key": key,
        "uid": uid,
        "pinWarn": "",
        "memberRole": user.role,
        "token": token,
        "memberWarn": "",
    }))
}

/// 入网成功后的落库 + 起循环。同步小操作,单独抽出来是为了让两条登录路共用同一份收尾。
pub(super) fn finish_enroll(url: &str, node_id: &str, out: &Value) -> Result<Value, String> {
    let key = out["key"]
        .as_str()
        .filter(|v| !v.is_empty())
        .ok_or("入网结果缺少设备密钥，未保存登录状态")?;
    let uid = out["uid"]
        .as_str()
        .filter(|v| !v.is_empty())
        .ok_or("入网结果缺少账号 UID，未保存登录状态")?;
    crate::collab::db::meta_set_many(&[(K_URL, url), (K_KEY, key), (K_UID, uid), ("mesh_node_id", node_id)])?;
    Ok(json!({
        "enrolled": true,
        "url": url,
        "uid": out["uid"],
        "email": out.get("email").cloned().unwrap_or(json!("")),
        "nodeId": node_id,
        "token": out["token"],
        // 两条「半成品」警告如实上报,UI 据此告诉用户「还差一步」而不是假装全好了:
        //  · pinWarn   :本机之前信任着**另一个**账号中心 → 别的设备连不进来;
        //  · memberWarn:这个账号还没成为本机成员(比如本机已有同名本地账号)→ 同上。
        "pinWarn": out["pinWarn"],
        "memberWarn": out["memberWarn"],
        "memberRole": out["memberRole"],
    }))
}

/// 入网地址:调用方填了就用它,没填看环境变量(server 形态),最后落到官方云机。
fn authority_of(url: Option<String>) -> Result<String, String> {
    let config = crate::collab::interconnect::load()?;
    if std::env::var_os("POLARIS_ACCOUNT_AUTHORITY_URL").is_some() {
        return Ok(config.authority.url.map_or_else(String::new, |url| url));
    }
    Ok(url.filter(|url| !url.trim().is_empty()).or(config.authority.url)
        .map_or_else(String::new, |url| url))
}

/// 拿一张**已有的**断言入网(手机壳/脚本等已经自己登过的场景)。
/// 桌面 UI 走的是 [`account_login_code`],不经过这里。
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn mesh_join(
    assertion: String,
    url: Option<String>,
    inviteCode: Option<String>,
    allowInsecureHttp: Option<bool>,
) -> Result<Value, String> {
    let node_id = my_node_id();
    if node_id.is_empty() {
        return Err("本机 P2P 身份生成失败(数据目录写不进去?)—— 换个数据目录再试".into());
    }
    let url = validate_authority_url(&authority_of(url)?, allowInsecureHttp.unwrap_or(false))?;
    let invite = inviteCode.unwrap_or_default();
    orchestration::complete_login(url, node_id, assertion, invite, false).await

}

/// Password and OTP login converge on the same enrollment/discovery/relay/connect sequence.
#[cfg_attr(feature = "desktop", tauri::command)]
#[allow(non_snake_case)]
pub async fn account_login_password(
    username: String, password: String, url: Option<String>,
    inviteCode: Option<String>, allowInsecureHttp: Option<bool>,
) -> Result<Value, String> {
    let url = validate_authority_url(&authority_of(url)?, allowInsecureHttp == Some(true))?;
    let node = my_node_id();
    if node.is_empty() { return Err("本机 P2P 身份尚未就绪".into()); }
    let endpoint = url.clone();
    let assertion = tokio::task::spawn_blocking(move || -> Result<String, String> {
        crate::collab::authority::pin_explicit(&endpoint)?;
        let response: Value = agent().post(&format!("{endpoint}/api/account/login"))
            .send_json(json!({"username": username, "password": password}))
            .map_err(cloud_err)?.into_json().map_err(|e| format!("账号中心 JSON 无效: {e}"))?;
        crate::collab::interconnect::apply_received_relays(&response)?;
        response["assertion"].as_str().map(String::from).ok_or_else(|| "账号中心缺少断言".into())
    }).await.map_err(|e| format!("密码登录任务失败: {e}"))??;
    orchestration::complete_login(
        url, node, assertion, inviteCode.map_or_else(String::new, |invite| invite), true,
    ).await
}

//! Authority directory generations. Re-enrolling a revoked NodeId creates a new device ID.
use crate::collab::{db, mesh};
use rusqlite::{params, Connection};
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Device {
    pub device_id: String,
    pub node_id: String,
    pub enrolled_at: i64,
    pub sequence: i64,
}

pub(crate) fn migrate(conn: &Connection) -> Result<(), String> {
    conn.execute_batch(include_str!("security.sql")).map_err(|e| e.to_string())
}

pub fn active(uid: &str, node: &str) -> Result<Device, String> {
    db::with_conn(|conn| {
        conn.query_row(
            "SELECT d.device_id,d.node_id,d.enrolled_at,d.sequence FROM mesh_device_ids d
             JOIN mesh_nodes m ON m.node_id=d.node_id AND m.uid=d.uid
             WHERE d.uid=?1 AND d.node_id=?2 AND m.revoked=0",
            params![uid, node], |r| Ok(Device {
                device_id: r.get(0)?, node_id: r.get(1)?, enrolled_at: r.get(2)?, sequence: r.get(3)?,
            }),
        ).map_err(|e| format!("设备未登记或已吊销: {e}"))
    })
}

pub fn active_devices(uid: &str) -> Result<Vec<Device>, String> {
    mesh::devices(uid)?.into_iter().filter(|(_, revoked)| !revoked)
        .map(|(peer, _)| active(uid, &peer.node_id)).collect()
}

/// Called inside the directory enrollment transaction, after updating mesh_nodes.
pub(crate) fn enrolled(conn: &Connection, uid: &str, node: &str) -> Result<(), String> {
    conn.execute(
        "INSERT INTO mesh_device_ids(node_id,uid,device_id,enrolled_at,sequence)
         SELECT node_id,uid,'dev_' || lower(hex(randomblob(16))),created_at,
         (SELECT COALESCE(MAX(sequence),0)+1 FROM mesh_device_ids) FROM mesh_nodes WHERE node_id=?1
         ON CONFLICT(node_id) DO UPDATE SET uid=excluded.uid,device_id=excluded.device_id,
         enrolled_at=excluded.enrolled_at,sequence=excluded.sequence
         WHERE mesh_device_ids.uid<>excluded.uid OR EXISTS(
             SELECT 1 FROM mesh_revocations r WHERE r.uid=mesh_device_ids.uid
             AND r.device_id=mesh_device_ids.device_id)", params![node],
    ).map_err(|e| e.to_string())?;
    // UID is checked here as well as in the caller to keep this boundary explicit.
    let matches: bool = conn.query_row(
        "SELECT EXISTS(SELECT 1 FROM mesh_device_ids WHERE node_id=?1 AND uid=?2)",
        params![node, uid], |r| r.get(0),
    ).map_err(|e| e.to_string())?;
    if !matches { return Err("设备账号不匹配".into()); }
    conn.execute("INSERT OR IGNORE INTO mesh_first_device(uid,device_id)
        SELECT uid,device_id FROM mesh_device_ids WHERE uid=?1 AND node_id=?2",
        params![uid, node]).map_err(|e| e.to_string())?;
    super::notifications::enrolled(conn, uid, node)?;
    Ok(())
}

pub(crate) fn revoked(conn: &Connection, uid: &str, node: &str) -> Result<(), String> {
    conn.execute(
        "INSERT INTO mesh_revocation_versions(uid,version) VALUES(?1,1)
         ON CONFLICT(uid) DO UPDATE SET version=version+1", params![uid],
    ).map_err(|e| e.to_string())?;
    conn.execute(
        "INSERT OR IGNORE INTO mesh_revocations(uid,device_id,node_id,revoked_at,version)
         SELECT d.uid,d.device_id,d.node_id,?3,v.version FROM mesh_device_ids d
         JOIN mesh_revocation_versions v ON v.uid=d.uid WHERE d.uid=?1 AND d.node_id=?2",
        params![uid, node, db::now()],
    ).map_err(|e| e.to_string())?;
    Ok(())
}
//! Device-bound federated sessions. Legacy assertions retain the old admission path with audit.
use crate::collab::{auth, authority::Claims, db, grants};
use rusqlite::{params, OptionalExtension};

pub fn node<'a>(claims: &'a Claims, supplied: &'a str) -> Result<&'a str, String> {
    match (&claims.device_id, &claims.node_id) {
        (Some(device), Some(node)) if !device.is_empty() && !node.is_empty() => {
            if !supplied.trim().is_empty() && supplied.trim() != node && supplied.trim() != device {
                return Err("断言绑定的 NodeId 与请求设备不符".into());
            }
            if super::revocations::is_revoked(&claims.uid, device)? {
                return Err("设备已被权威吊销".into());
            }
            if grants::is_revoked(node) { return Err("设备已被本机撤销".into()); }
            Ok(node)
        }
        (None, None) => {
            eprintln!("[auth] legacy_unbound_assertion uid={}", claims.uid);
            db::audit(&claims.username, "auth.legacy_unbound_assertion", supplied, &claims.uid);
            Ok(supplied.trim())
        }
        _ => Err("断言设备绑定字段不完整".into()),
    }
}

pub fn issue(user_id: i64, claims: &Claims, supplied: &str) -> Result<String, String> {
    let node = node(claims, supplied)?;
    let Some(device) = &claims.device_id else { return auth::issue_session(user_id, node); };
    let token = auth::random_token();
    let mut conn = db::open_db()?;
    let tx = conn.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|e| e.to_string())?;
    // Recheck under the same write transaction as insertion; sync cannot race issuance.
    let revoked: bool = tx.query_row(
        "SELECT EXISTS(SELECT 1 FROM cached_revocations WHERE uid=?1 AND device_id=?2)
         OR EXISTS(SELECT 1 FROM mesh_revocations WHERE uid=?1 AND device_id=?2)",
        params![claims.uid, device], |r| r.get(0),
    ).map_err(|e| e.to_string())?;
    if revoked { return Err("设备已被权威吊销".into()); }
    auth::insert_session_tx(&tx, &token, user_id, device)?;
    tx.execute("INSERT INTO bound_sessions(token,uid,device_id,node_id) VALUES(?1,?2,?3,?4)",
        params![token, claims.uid, device, node]).map_err(|e| e.to_string())?;
    tx.commit().map_err(|e| e.to_string())?;
    Ok(token)
}

/// Called before the short session cache on every request. Offline checks stay entirely local.
pub fn check(token: &str) -> Result<(), String> {
    let binding: Option<(String, String)> = db::with_conn(|conn| conn.query_row(
        "SELECT uid,device_id FROM bound_sessions WHERE token=?1", params![token],
        |r| Ok((r.get(0)?, r.get(1)?)),
    ).optional().map_err(|e| e.to_string()))?;
    if let Some((uid, device)) = binding {
        if super::revocations::is_revoked(&uid, &device)? {
            auth::logout(token)?;
            return Err("设备已被权威吊销".into());
        }
    }
    Ok(())
}
//! Shared high-risk adapter for HTTP actors and the local mesh console.
use crate::collab::{authority, db};
use rusqlite::{params, OptionalExtension};
use serde_json::{json, Value};

pub fn require(uid: &str, actor_node: &str, operation: &str, payload: &Value) -> Result<(), String> {
    require_proven(uid, actor_node, operation, payload, None)
}

pub fn require_proven(
    uid: &str, actor_node: &str, operation: &str, payload: &Value, assertion: Option<&str>,
) -> Result<(), String> {
    if uid.is_empty() { return Ok(()); }
    let digest = super::risk::digest(operation, payload);
    let nonce = crate::collab::auth::random_token();
    if authority::is_authority() {
        super::risk::authorize(uid, actor_node, actor_node, operation, &digest, &nonce)?;
        return Ok(());
    }
    let snapshot = super::revocations::cached(uid)?;
    let actor = snapshot.devices.iter().find(|device| device.node_id == actor_node)
        .ok_or("需要联网确认：最新清单尚未包含当前设备")?;
    if super::revocations::is_revoked(uid, &actor.device_id)? { return Err("设备已吊销".into()); }
    let window = super::load()?.security.new_device_window_hours as i64 * 3600;
    if snapshot.devices.len() == 1 || snapshot.first_device.as_deref() == Some(&actor.device_id)
        || db::now() >= actor.enrolled_at + window
    { return Ok(()); }
    let (url, key, _) = authority::pinned().ok_or("需要联网确认：尚未信任权威")?;
    let mesh_key = db::meta_get("mesh_key").ok_or("需要联网确认：本机尚未入网")?;
    let response = ureq::AgentBuilder::new().timeout(std::time::Duration::from_secs(10)).build()
        .post(&format!("{url}/api/mesh/risk/authorize"))
        .set("Authorization", &format!("Bearer {mesh_key}"))
        .send_json(json!({"actorNodeId":actor_node, "operation":operation, "digest":digest, "nonce":nonce, "actorAssertion":assertion}));
    let response: Value = match response {
        Ok(response) => response.into_json().map_err(|e| e.to_string())?,
        Err(ureq::Error::Status(_, response)) => {
            let value: Value = response.into_json().map_err(|e| e.to_string())?;
            return Err(value["error"].as_str().map_or_else(|| "需要联网确认".into(), String::from));
        }
        Err(error) => return Err(format!("需要联网确认：{error}")),
    };
    let document = response["permit"].as_str().ok_or("需要联网确认：权威未返回签名批准")?;
    let config = super::load()?;
    if !config.authority.public_key_fingerprints.is_empty() { config.verify_key(&key)?; }
    let permit: super::risk::Permit = authority::verify_document("PRISK1", document, &key)?;
    let host = db::meta_get("mesh_node_id").map_or_else(String::new, |v| v);
    if permit.uid != uid || permit.digest != digest || permit.nonce != nonce
        || permit.expires_at <= db::now() || permit.host != host
        || actor.device_id != permit.actor
    { return Err("高风险批准与当前设备、主机或操作不匹配".into()); }
    Ok(())
}

/// Legacy assertions retain their prior policy; bound sessions must use the approval gate.
pub fn session(token: &str, operation: &str, payload: &Value) -> Result<(), String> {
    session_proven(token, operation, payload, None)
}

pub fn session_proven(token: &str, operation: &str, payload: &Value, assertion: Option<&str>) -> Result<(), String> {
    crate::collab::auth::check_session(token)?;
    let binding: Option<(String, String)> = db::with_conn(|conn| conn.query_row(
        "SELECT uid,node_id FROM bound_sessions WHERE token=?1", params![token],
        |r| Ok((r.get(0)?, r.get(1)?)),
    ).optional().map_err(|e| e.to_string()))?;
    if let Some((uid, node)) = binding { require_proven(&uid, &node, operation, payload, assertion)?; }
    Ok(())
}
//! collab/mesh.rs —— 同账号设备网的**设备目录**(权威侧)。
//!
//! 解决的问题:此前接入一台远程主机要手工粘一串 PLRK1 连接码,N 台设备两两互连是 N² 次
//! 粘贴。Tailscale 的体验是「登录同一个账号 → 设备自己就成了网」。这张目录就是那个
//! 「自己成网」缺的一环:每台设备登录后把自己的 iroh NodeId 挂上来,同 uid 的其它设备
//! 拉一次清单就知道该连谁。
//!
//! **只有账号权威(云机)跑这张表。** 成员主机不存别人的设备,也不需要 —— 它们只是
//! 向权威报到、取清单。
//!
//! 凭据设计(这里是本模块唯一需要小心的地方):
//!  · 入网时权威颁一把**设备密钥**(32 字节随机),库里只留 sha256,明文只在颁发那一次回给设备。
//!  · 这把密钥能做两件事:报到取清单、以及**换取一张身份断言**。后者意味着它等同该账号的
//!    长期凭据 —— 所以按设备独立颁发、可按设备独立吊销,丢一台不必改密码。
//!  · 密钥**不用来直接访问别的设备**。设备之间进门仍走原来那条路:拿断言去对端换本机会话
//!    ([`super::authority::login_with_assertion`])。于是「谁能进我的机器」始终由**对端自己的
//!    成员资格**说了算,云机从不持有任何一台设备的访问权 —— 云机被拿下也开不了你家的盘。
use base64::Engine;
use rusqlite::{params, OptionalExtension};
use serde::Serialize;
use sha2::{Digest, Sha256};

use super::db::{self, now, open_db};

const B64: base64::engine::general_purpose::GeneralPurpose =
    base64::engine::general_purpose::URL_SAFE_NO_PAD;

/// 设备心跳周期(客户端 60s 一次)的 3 倍余量:超过这个没报到就算离线。
const ONLINE_WINDOW: i64 = 200;

#[derive(Serialize, Clone, Debug)]
pub struct Peer {
    pub node_id: String,
    pub name: String,
    pub os: String,
    pub ver: String,
    pub last_seen: i64,
    pub online: bool,
    /// 这台机器**第一次**入网的时刻。created_at 会被重登覆盖(同 NodeId 换密钥即 upsert),
    /// 留不住真正的首见时间,而设备台账要显示它 —— 「这台是三天前才冒出来的」是个安全信号。
    #[serde(default)]
    pub first_seen: i64,
}

fn hash_key(k: &str) -> String {
    let d = Sha256::digest(k.as_bytes());
    d.iter().map(|b| format!("{b:02x}")).collect()
}

fn new_key() -> Result<String, String> {
    let mut buf = [0u8; 32];
    getrandom::getrandom(&mut buf).map_err(|e| format!("生成设备密钥失败: {e}"))?;
    Ok(format!("mk_{}", B64.encode(buf)))
}

fn row_to_peer(
    r: &rusqlite::Row,
    t: i64,
) -> rusqlite::Result<Peer> {
    let last_seen: i64 = r.get(4)?;
    Ok(Peer {
        node_id: r.get(0)?,
        name: r.get(1)?,
        os: r.get(2)?,
        ver: r.get(3)?,
        last_seen,
        online: t - last_seen <= ONLINE_WINDOW,
        first_seen: r.get(5).unwrap_or(0),
    })
}

const PEER_COLS: &str = "node_id,name,os,ver,last_seen,first_seen";

/// 设备入网:登记 NodeId 并颁一把新的设备密钥(返回明文,只此一次)。
///
/// 同 node_id 再来 = **换一把新密钥**(重装、重新登录都走这条)。这是有意的幂等口径:
/// 一台机器的身份是它的 NodeId,不是密钥;重登不该在目录里堆出第二个「同一台机器」。
/// 顺带把 revoked 清零 —— 用户亲自重新登录进来,就是撤回了那次吊销。
pub fn enroll(uid: &str, node_id: &str, name: &str, os: &str, ver: &str) -> Result<String, String> {
    let node_id = node_id.trim();
    if node_id.is_empty() {
        return Err("设备缺 NodeId(本机 iroh 还没就绪,稍后重试)".into());
    }
    if uid.trim().is_empty() {
        return Err("缺账号 uid".into());
    }
    let key = new_key()?;
    let mut connection = open_db()?;
    let conn = connection.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|e| e.to_string())?;
    let existing_uid: Option<String> = conn.query_row(
        "SELECT uid FROM mesh_nodes WHERE node_id=?1", params![node_id], |r| r.get(0),
    ).optional().map_err(|e| e.to_string())?;
    if existing_uid.is_some_and(|existing| existing != uid.trim()) {
        return Err("该 NodeId 已登记到其他账号".into());
    }
    // first_seen 用 excluded 会被重登覆盖 —— 这里刻意保留旧值(COALESCE 兜住老行的 0),
    // 因为台账要回答的是「这台机器什么时候第一次出现在我账号里」,不是「上次重登是几点」。
    conn.execute(
        "INSERT INTO mesh_nodes(node_id,uid,name,os,ver,key_hash,created_at,last_seen,revoked,first_seen) \
         VALUES(?1,?2,?3,?4,?5,?6,?7,?7,0,?7) \
         ON CONFLICT(node_id) DO UPDATE SET \
           uid=excluded.uid, name=excluded.name, os=excluded.os, ver=excluded.ver, \
           key_hash=excluded.key_hash, created_at=excluded.created_at, last_seen=excluded.last_seen, revoked=0, \
           first_seen=CASE WHEN mesh_nodes.first_seen>0 THEN mesh_nodes.first_seen ELSE excluded.first_seen END",
        params![node_id, uid.trim(), name.trim(), os.trim(), ver.trim(), hash_key(&key), now()],
    )
    .map_err(|e| format!("设备入网失败: {e}"))?;
    super::interconnect::devices::enrolled(&conn, uid, node_id)?;
    conn.commit().map_err(|e| e.to_string())?;
    super::interconnect::notifications::wake();
    db::audit(uid, "mesh.enroll", node_id, name);
    Ok(key)
}

/// 设备密钥 → (uid, node_id)。吊销的、不认识的一律拒。
pub fn resolve_key(key: &str) -> Result<(String, String), String> {
    let conn = open_db()?;
    let row: Option<(String, String, i64)> = conn
        .query_row(
            "SELECT uid,node_id,revoked FROM mesh_nodes WHERE key_hash=?1",
            params![hash_key(key.trim())],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
        )
        .optional()
        .map_err(|e| format!("查设备失败: {e}"))?;
    match row {
        Some((_, _, revoked)) if revoked != 0 => {
            Err("这台设备已被移出设备网 —— 重新登录账号即可重新入网".into())
        }
        Some((uid, node_id, _)) => Ok((uid, node_id)),
        None => Err("设备密钥无效 —— 请重新登录账号入网".into()),
    }
}

/// 同一账号名下的其它设备(不含自己)。吊销的不出现在清单里。
pub fn peers(uid: &str, exclude_node: &str) -> Result<Vec<Peer>, String> {
    let t = now();
    let conn = open_db()?;
    let mut st = conn
        .prepare(&format!(
            "SELECT {PEER_COLS} FROM mesh_nodes \
             WHERE uid=?1 AND revoked=0 AND node_id<>?2 ORDER BY last_seen DESC"
        ))
        .map_err(|e| format!("查设备清单失败: {e}"))?;
    let rows = st
        .query_map(params![uid, exclude_node], |r| row_to_peer(r, t))
        .map_err(|e| format!("查设备清单失败: {e}"))?;
    Ok(rows.flatten().collect())
}

/// 设备**台账**:同一账号名下的全部设备,**含自己那台**,也含已被移出的。
///
/// 与 [`peers`] 的分工:那个是给对账循环用的「我该连谁」,所以排掉自己、排掉已吊销的;
/// 这个是给人看的,少一台都是缺陷 —— 用户要在台账上认出「哪台是我正在用的这台」,
/// 也要看见「上周被我踢掉的那台还在不在」。
pub fn devices(uid: &str) -> Result<Vec<(Peer, bool)>, String> {
    let t = now();
    let conn = open_db()?;
    let mut st = conn
        .prepare(&format!(
            "SELECT {PEER_COLS},revoked FROM mesh_nodes WHERE uid=?1 \
             ORDER BY revoked ASC, last_seen DESC"
        ))
        .map_err(|e| format!("查设备台账失败: {e}"))?;
    let rows = st
        .query_map(params![uid], |r| {
            Ok((row_to_peer(r, t)?, r.get::<_, i64>(6)? != 0))
        })
        .map_err(|e| format!("查设备台账失败: {e}"))?;
    Ok(rows.flatten().collect())
}

/// 给设备改个人话名字(台账上的「改名」)。
///
/// 为什么需要它:名字本来跟着 announce 走 = 机器名,一屋子 `DESKTOP-1D01IJR` 认不出谁是谁。
/// 改过名的设备打上 named 标记,此后 announce 不再用机器名覆盖它 —— 否则用户改完,
/// 下一拍心跳就给改回去了。
pub fn rename(uid: &str, node_id: &str, name: &str) -> Result<(), String> {
    let name = name.trim();
    if name.is_empty() || name.chars().count() > 40 {
        return Err("设备名长度须为 1–40 个字符".into());
    }
    let conn = open_db()?;
    let n = conn
        .execute(
            "UPDATE mesh_nodes SET name=?3 WHERE node_id=?1 AND uid=?2",
            params![node_id.trim(), uid, name],
        )
        .map_err(|e| format!("改设备名失败: {e}"))?;
    if n == 0 {
        return Err("这台设备不在你账号的设备网里".into());
    }
    // 记住「这个名字是人取的」,announce 从此不覆盖它。
    let _ = conn.execute(
        "INSERT INTO meta(k,v) VALUES(?1,'1') ON CONFLICT(k) DO UPDATE SET v='1'",
        params![named_key(node_id)],
    );
    db::audit(uid, "mesh.rename", node_id.trim(), name);
    Ok(())
}

/// 「这台设备的名字是人手取的」标记键。
fn named_key(node_id: &str) -> String {
    format!("mesh_named_{}", node_id.trim())
}

/// 心跳 + 取清单(一次往返办两件事:设备网的轮询频率不低,能省一趟就省一趟)。
pub fn announce(key: &str, name: &str, os: &str, ver: &str) -> Result<(String, Vec<Peer>), String> {
    let (uid, node_id) = resolve_key(key)?;
    let conn = open_db()?;
    // 用户在台账上手工改过名的设备,心跳不许再拿机器名覆盖回去 ——
    // 否则「改名」这个动作最多活 60 秒,下一拍就被打回原形。
    let human_named = db::meta_get(&named_key(&node_id)).as_deref() == Some("1");
    let name = if human_named { "" } else { name };
    // 名字/版本每次报到都跟着更新:改了机器名、升了版本,清单里立刻是新的。
    conn.execute(
        "UPDATE mesh_nodes SET last_seen=?1, \
           name=CASE WHEN ?2<>'' THEN ?2 ELSE name END, \
           os=CASE WHEN ?3<>'' THEN ?3 ELSE os END, \
           ver=CASE WHEN ?4<>'' THEN ?4 ELSE ver END \
         WHERE node_id=?5",
        params![now(), name.trim(), os.trim(), ver.trim(), node_id],
    )
    .map_err(|e| format!("设备报到失败: {e}"))?;
    let list = peers(&uid, &node_id)?;
    Ok((uid, list))
}

/// 把自己账号名下的一台设备移出设备网(丢了电脑的应急操作)。
/// 只能踢**同 uid** 的设备 —— 拿着自己的密钥踢不掉别人账号的机器。
pub fn revoke(uid: &str, node_id: &str) -> Result<(), String> {
    let mut connection = open_db()?;
    let conn = connection.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|e| e.to_string())?;
    let n = conn
        .execute(
            "UPDATE mesh_nodes SET revoked=1 WHERE node_id=?1 AND uid=?2",
            params![node_id.trim(), uid],
        )
        .map_err(|e| format!("移出设备网失败: {e}"))?;
    if n == 0 {
        return Err("这台设备不在你账号的设备网里".into());
    }
    super::interconnect::devices::revoked(&conn, uid, node_id)?;
    conn.commit().map_err(|e| e.to_string())?;
    super::interconnect::notifications::wake();
    db::audit(uid, "mesh.revoke", node_id, "");
    Ok(())
}

/// uid → (username, email, display_name)。给设备换取身份断言时填断言载荷用。
pub fn account_of(uid: &str) -> Result<(String, String, String), String> {
    let conn = open_db()?;
    conn.query_row(
        "SELECT username,email,display_name,disabled FROM users WHERE uid=?1",
        params![uid],
        |r| {
            Ok((
                r.get::<_, String>(0)?,
                r.get::<_, String>(1)?,
                r.get::<_, String>(2)?,
                r.get::<_, i64>(3)?,
            ))
        },
    )
    .optional()
    .map_err(|e| format!("查账号失败: {e}"))?
    .ok_or_else(|| "这个账号在账号中心已不存在".to_string())
    .and_then(|(u, e, d, disabled)| {
        if disabled != 0 {
            Err("账号已停用".into())
        } else {
            Ok((u, e, d))
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp_db(tag: &str) -> std::sync::MutexGuard<'static, ()> {
        let g = db::TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let p = std::env::temp_dir().join(format!("mesh-test-{}-{tag}.db", std::process::id()));
        let _ = std::fs::remove_file(&p);
        std::env::set_var("POLARIS_COLLAB_DB", &p);
        g
    }

    /// 入网 → 报到 → 互见:两台设备同一个 uid,各自只看见对方。
    #[test]
    fn two_devices_of_one_account_see_each_other() {
        let _g = tmp_db("pair");
        let k1 = enroll("acct_1", "node-aaa", "台式机", "windows", "2.6.0").unwrap();
        let k2 = enroll("acct_1", "node-bbb", "NAS", "linux", "2.6.0").unwrap();
        assert_ne!(k1, k2, "每台设备一把独立密钥");

        let (uid, p1) = announce(&k1, "台式机", "windows", "2.6.0").unwrap();
        assert_eq!(uid, "acct_1");
        assert_eq!(p1.len(), 1, "只该看见对方一台");
        assert_eq!(p1[0].node_id, "node-bbb");
        assert!(p1[0].online, "刚报到过必须算在线");

        let (_, p2) = announce(&k2, "NAS", "linux", "2.6.0").unwrap();
        assert_eq!(p2[0].node_id, "node-aaa");
    }

    /// 账号隔离:别人账号的设备绝不出现在我的清单里。
    #[test]
    fn other_accounts_are_invisible() {
        let _g = tmp_db("iso");
        let mine = enroll("acct_me", "node-mine", "我的", "windows", "1").unwrap();
        enroll("acct_other", "node-other", "别人的", "linux", "1").unwrap();
        let (_, list) = announce(&mine, "", "", "").unwrap();
        assert!(list.is_empty(), "看见了不属于本账号的设备:{list:?}");
    }

    /// 吊销即失效:密钥不能再报到;本人重新登录(再 enroll)可自助恢复。
    #[test]
    fn revoke_then_reenroll() {
        let _g = tmp_db("revoke");
        let k = enroll("acct_1", "node-x", "旧机", "windows", "1").unwrap();
        enroll("acct_1", "node-y", "另一台", "windows", "1").unwrap();

        revoke("acct_1", "node-x").unwrap();
        assert!(announce(&k, "", "", "").is_err(), "吊销后不该还能报到");
        // 别人的账号踢不动我的设备。
        assert!(revoke("acct_other", "node-y").is_err());

        // 重新入网:拿到新密钥,旧密钥永久作废。
        let k2 = enroll("acct_1", "node-x", "旧机", "windows", "1").unwrap();
        assert!(announce(&k2, "", "", "").is_ok());
        assert!(announce(&k, "", "", "").is_err(), "旧密钥必须仍然无效");
    }

    /// 重复入网不制造重影:同一台机器登两次,目录里仍是一台。
    #[test]
    fn reenroll_is_idempotent_on_node_id() {
        let _g = tmp_db("dup");
        enroll("acct_1", "node-a", "机器", "windows", "1").unwrap();
        let k = enroll("acct_1", "node-a", "机器改了名", "windows", "2").unwrap();
        enroll("acct_1", "node-b", "另一台", "linux", "1").unwrap();
        let (_, list) = announce(&k, "", "", "").unwrap();
        assert_eq!(list.len(), 1, "同 node_id 重复入网不该多出一台:{list:?}");
    }

    /// 台账:含自己、含已移出的;改过名之后心跳不许把名字打回原形。
    #[test]
    fn ledger_lists_all_and_keeps_human_names() {
        let _g = tmp_db("ledger");
        let k1 = enroll("acct_1", "node-a", "DESKTOP-1D01IJR", "windows", "2.9.0").unwrap();
        enroll("acct_1", "node-b", "NAS", "linux", "2.9.0").unwrap();
        enroll("acct_1", "node-c", "旧笔记本", "windows", "2.7.0").unwrap();
        revoke("acct_1", "node-c").unwrap();

        let list = devices("acct_1").unwrap();
        assert_eq!(list.len(), 3, "台账要含自己那台和已移出的那台:{list:?}");
        assert!(list.iter().any(|(p, rev)| p.node_id == "node-c" && *rev));
        assert!(list.iter().all(|(p, _)| p.first_seen > 0), "首见时刻要落下来");

        // 改名 → 心跳带着机器名再来一次 → 名字必须还是人取的那个。
        rename("acct_1", "node-a", "书房台式机").unwrap();
        announce(&k1, "DESKTOP-1D01IJR", "windows", "2.9.0").unwrap();
        let list = devices("acct_1").unwrap();
        let a = list.iter().find(|(p, _)| p.node_id == "node-a").unwrap();
        assert_eq!(a.0.name, "书房台式机", "手工改的名被心跳覆盖了");

        // 改不了别人账号的设备名。
        assert!(rename("acct_other", "node-a", "偷改").is_err());
        assert!(rename("acct_1", "node-a", "").is_err());
    }

    /// 重复入网不该把「第一次见到这台机器」的时刻冲掉(安全信号要留得住)。
    #[test]
    fn first_seen_survives_reenroll() {
        let _g = tmp_db("firstseen");
        enroll("acct_1", "node-a", "机器", "windows", "1").unwrap();
        let first = devices("acct_1").unwrap()[0].0.first_seen;
        assert!(first > 0);
        std::thread::sleep(std::time::Duration::from_millis(1100));
        enroll("acct_1", "node-a", "机器", "windows", "2").unwrap();
        assert_eq!(devices("acct_1").unwrap()[0].0.first_seen, first);
    }

    #[test]
    fn bad_key_is_refused() {
        let _g = tmp_db("badkey");
        enroll("acct_1", "node-a", "机器", "windows", "1").unwrap();
        assert!(resolve_key("mk_totally-made-up").is_err());
        assert!(announce("", "", "", "").is_err());
    }
}

import { ref } from 'vue';
import { errMsg } from '../../lib/err';
import { interconnectCopy as c } from './copy';
import type { Command, Progress, RelayConfig } from './contracts';

export interface LoginResult {
  enrolled?: boolean; token?: string; interconnect?: Progress; relayConfig?: RelayConfig;
  authorityConfigured?: boolean; configurationError?: string;
}
export function useLogin(command: Command, adopt: (token: string) => Promise<void>, slowMs: number) {
  const progress = ref<Progress | null>(null);
  const relay = ref<RelayConfig>();
  const error = ref('');
  const busy = ref(false);
  const enrolled = ref(false);
  const authorityConfigured = ref<boolean>();
  let pollBusy = false;
  let disposed = false;
  function receive(result: LoginResult) {
    if (disposed) return;
    if (result.interconnect) progress.value = result.interconnect;
    if (result.relayConfig) relay.value = result.relayConfig;
    if (result.enrolled !== undefined) enrolled.value = result.enrolled;
    if (result.authorityConfigured !== undefined) authorityConfigured.value = result.authorityConfigured;
    if (result.configurationError) error.value = result.configurationError;
  }
  async function refresh() {
    if (pollBusy || disposed) return;
    pollBusy = true;
    try { receive(await command<LoginResult>('mesh_status')); }
    catch (e) { if (!disposed) error.value = errMsg(e); }
    finally { pollBusy = false; }
  }
  async function done(result: LoginResult) {
    receive(result);
    if (result.token) await adopt(result.token);
  }
  async function execute(action: () => Promise<LoginResult>) {
    if (busy.value || disposed) return;
    busy.value = true;
    error.value = '';
    const timer = setTimeout(() => { if (!disposed) error.value = c.timeout; }, slowMs);
    try {
      const result = await action();
      if (!disposed) error.value = '';
      await done(result);
    }
    catch (e) {
      if (!disposed) {
        error.value = errMsg(e);
        if (progress.value?.state !== 'failed') progress.value = null;
      }
    }
    finally { clearTimeout(timer); busy.value = false; }
  }
  async function login(username: string, password: string) {
    progress.value = null;
    await execute(async () => {
      await command('collab_host_start');
      return command<LoginResult>('account_login_password', { username, password });
    });
  }
  async function retry() {
    if (!enrolled.value || progress.value?.stage === 'register') return;
    await execute(() => command<LoginResult>('mesh_sync'));
    await refresh();
  }
  function dispose() { disposed = true; }
  return { progress, relay, error, busy, enrolled, authorityConfigured, receive, refresh, done, login, retry, dispose };
}
import { onMounted, onUnmounted, watch, ref } from 'vue';
import { invoke as rawInvoke, isTauri, listen } from '../../tauri';
import { useCollabStore } from '../collab/stores/collab';
import { useAccountStore } from '../../stores/account';
import { useLogin, type LoginResult } from './useLogin';
import { useSecurity } from './useSecurity';
import { timing, type Approval, type Device, type Notice, type Progress, type Timing } from './contracts';
import { interconnectCopy as c } from './copy';
import { errMsg } from '../../lib/err';

const riskCommands = new Set(['peer_grant_set', 'peer_trust', 'peer_revoke', 'mesh_device_remove',
  'mesh_kick', 'mesh_leave', 'fs_unmount', 'fs_share_save', 'fs_share_set']);
export function useInterconnect(
  collab: ReturnType<typeof useCollabStore>, account: ReturnType<typeof useAccountStore>,
  changed: () => Promise<void>, options: Partial<Timing> = {},
) {
  const config = timing(options);
  const login = useLogin(rawInvoke, async token => {
    await collab.adoptLocalSession(token);
    await account.refresh();
    await changed();
  }, config.slowMs);
  const security = useSecurity(rawInvoke);
  const ports = ref<Record<string, number>>({});
  const stops: (() => void)[] = [];
  let disposed = false;
  let poll: ReturnType<typeof setInterval>;
  let retry: ReturnType<typeof setInterval>;
  let polling = false;
  async function refresh() {
    if (!isTauri || polling || disposed) return;
    polling = true;
    try {
      await login.refresh();
      if (collab.authed && login.enrolled.value) {
        await security.refresh();
        const state = await rawInvoke<{ peers?: { nodeId: string; port: number }[] }>('mesh_status');
        if (!disposed) ports.value = Object.fromEntries((state.peers || []).map(p => [p.nodeId, p.port]));
      }
    } catch (e) { if (!disposed) login.error.value = errMsg(e); }
    finally { polling = false; }
  }
  async function passwordLogin(username: string, password: string) {
    if (isTauri) await login.login(username, password);
    else {
      login.busy.value = true;
      login.error.value = '';
      try { await collab.login(username, password); await account.refresh(); }
      catch (e) { login.error.value = errMsg(e); }
      finally { login.busy.value = false; }
    }
    await refresh();
  }
  async function emailDone(info: Record<string, unknown>) {
    await login.done(info as LoginResult);
    await changed();
    await refresh();
  }
  async function logout() {
    await security.run(async () => {
      // Gate before account.logout, which otherwise clears the session even when mesh_leave is pending.
      if (isTauri) await rawInvoke('mesh_leave');
      await collab.logout();
      await account.refresh();
      login.enrolled.value = false;
      login.progress.value = null;
      await changed();
    });
  }
  async function invoke<T>(name: string, args?: Record<string, unknown>): Promise<T> {
    if (!riskCommands.has(name)) return rawInvoke<T>(name, args);
    const payload = args ? JSON.parse(JSON.stringify(args)) as Record<string, unknown> : undefined;
    let result: T | undefined;
    let completed = false;
    await security.run(async () => {
      result = await rawInvoke<T>(name, payload);
      if ((result as { partial?: boolean })?.partial) throw new Error(c.partial);
      completed = true;
      void changed().catch(e => { login.error.value = errMsg(e); });
    });
    if (!completed) throw new Error(security.pending.value ? c.waiting : security.error.value);
    return result as T;
  }
