/// accept 与转发互相饿死,超过 8 个对这种 IO 型负载没有收益。`POLARIS_TUNNEL_WORKERS` 可调。
fn tunnel_workers() -> usize {
    std::env::var("POLARIS_TUNNEL_WORKERS")
        .ok()
        .and_then(|v| v.trim().parse::<usize>().ok())
        .filter(|v| *v > 0)
        .unwrap_or_else(|| {
            std::thread::available_parallelism()
                .map(|n| n.get())
                .unwrap_or(2)
