            &claims.uid,
            &s_of(&v, "nodeId"),
            &s_of(&v, "name"),
            &s_of(&v, "os"),
            &s_of(&v, "ver"),
        )?;
        Ok(json!({ "meshKey": key, "uid": claims.uid, "username": claims.username,
            "relays": crate::collab::interconnect::advertised_relays()? }))
    })
    .await;
    unwrap_api(out)
}

