# ═══════════════════════════════════════════════════════════════
# polaris-collab — 多人协作引擎 crate(分仓规划 v2 第 5 仓的仓内形态)
# 账号/授权表/任务卡/合并闸门/检查工作流/Gitea/iroh 隧道/云中继网关。
# 边界铁律: 只准向下依赖 polaris-kernel(skills 检查技能)与 polaris-runtime(host shim);
#   应用数据面 apihub 与桌面内嵌主机 hosting 是壳件, 留在 polaris-app —— 本 crate
#   不认识 kb/chat/fable 等任何同层引擎, 编译器物理保证。
# 特性: collab-host(axum 协作路由) / collab-net(iroh 隧道+云中继) / desktop(tauri 命令)。
# ═══════════════════════════════════════════════════════════════
[package]
name = "polaris-collab"
version = "0.1.0"
edition = "2021"
publish = false

[dependencies]
polaris-kernel = { path = "../polaris-kernel" }
polaris-runtime = { path = "../polaris-runtime" }
# 版本与主 crate 逐条对齐(同 workspace 共享编译产物,零增量)
serde = { version = "1", features = ["derive"] }
serde_json = "1"
anyhow = "1"
once_cell = "1"
parking_lot = "0.12"
regex = "1"
directories = "5"
walkdir = "2"
ureq = { version = "2", features = ["json"] }
base64 = "0.22"
hex = "0.4"
sha2 = "0.10"
getrandom = "0.2"
chrono = { version = "0.4", default-features = false, features = ["clock"] }
rusqlite = { version = "0.32", features = ["bundled"] }
# 账号密码哈希(argon2id PHC)与账号镜像加密(云端零知识)
argon2 = "0.5"
chacha20poly1305 = "0.10"
# 账号权威签名(Ed25519):云机签身份断言,成员主机离线验签 —— 不进 collab-net,
# 因为**普通桌面主机也要验签**,而它不编 iroh。
ed25519-dalek = { version = "2", default-features = false, features = ["std"] }
tokio = { version = "1", features = ["time", "macros", "rt-multi-thread", "sync", "net", "io-util", "signal"] }
tauri = { version = "2.1", features = [], optional = true }
# 协作路由(collab-host)
axum = { version = "0.7", features = ["ws", "multipart"], optional = true }
# 邮箱验证码(注册/找回密码)发信:阻塞 SMTP + rustls(避开 OpenSSL,QQ 邮箱 465 隐式 TLS)
lettre = { version = "0.11", default-features = false, features = ["smtp-transport", "builder", "hostname", "rustls-tls"], optional = true }
# 远程盘读文件的传输压缩(Accept-Encoding: zstd 时才启用)。这棵依赖本来就在树里
# (zip → polaris-kernel),这里只是显式点名,不新增编译负担。
zstd = { version = "0.13", optional = true }
tower = { version = "0.5", optional = true }
tower-http = { version = "0.6", features = ["fs", "cors", "trace"], optional = true }
futures-util = { version = "0.3", optional = true }
# 组网隧道 + 云中继(collab-net):iroh 依赖树大,默认不进
iroh = { version = "1", optional = true }
# mDNS 局域网发现:纯内网(无外网,n0 DNS/relay 全不可达)时,同网段设备也能互相发现直连
iroh-mdns-address-lookup = { version = "0.4", optional = true }
tokio-tungstenite = { version = "0.24", optional = true }

[features]
default = []
desktop = ["dep:tauri"]
collab-host = ["dep:axum", "dep:tower", "dep:tower-http", "dep:futures-util", "dep:lettre", "dep:zstd"]
collab-net = ["dep:iroh", "dep:iroh-mdns-address-lookup", "dep:tokio-tungstenite"]

pub fn resolve(
    user_json: Option<&str>,
    env: impl Fn(&str) -> Option<String>,
) -> Result<Config, String> {
    let mut value: serde_json::Value = serde_json::from_str(DEFAULTS).map_err(|e| e.to_string())?;
    if let Some(raw) = user_json {
        let user: serde_json::Value = serde_json::from_str(raw)
            .map_err(|e| format!("互联用户配置不是合法 JSON: {e}"))?;
        if !user.is_object() {
            return Err("互联配置必须是 JSON 对象".into());
        }
        merge(&mut value, user);
    }
    // Deserialize before applying env to avoid panics from indexing malformed user JSON.
    let mut config: Config = serde_json::from_value(value)
        .map_err(|e| format!("互联配置类型错误: {e}"))?;
    if let Some(url) = env("POLARIS_ACCOUNT_AUTHORITY_URL") {
        config.authority.url = Some(url);
    }
    if let Some(raw) = env("POLARIS_ACCOUNT_AUTHORITY_PUBLIC_KEY_FINGERPRINTS") {
        config.authority.public_key_fingerprints = csv(&raw);
    }
    if let Some(raw) = env("POLARIS_RELAYS") {
        config.relay.urls = csv(&raw);
    }
    if let Some(raw) = env("POLARIS_RELAY_FALLBACK") {
        config.relay.fallback = match raw.as_str() {
            "true" | "1" => true,
            "false" | "0" => false,
            _ => return Err("POLARIS_RELAY_FALLBACK 须为 true/false/1/0".into()),
        };
    }
    config.authority.url = config.authority.url
        .map(|v| v.trim().trim_end_matches('/').to_string())
        .filter(|v| !v.is_empty());
    if let Some(url) = &config.authority.url {
        validate_url(url)?;
    }
    for fp in &mut config.authority.public_key_fingerprints {
        if fp.len() != 64 || !fp.bytes().all(|c| c.is_ascii_hexdigit()) {
            return Err("权威预置指纹必须为完整 SHA-256（64 位十六进制），不能使用短 kid".into());
        }
        fp.make_ascii_lowercase();
    }
    for url in &config.relay.urls {
        validate_url(url)?;
    }
    for (name, value, max) in [
        ("revocationPollSecs", config.security.revocation_poll_secs, 3600),
        ("revocationMaxAgeSecs", config.security.revocation_max_age_secs, 86400),
        ("newDeviceWindowHours", config.security.new_device_window_hours, 720),
        ("approvalTimeoutSecs", config.security.approval_timeout_secs, 3600),
    ] {
        if value == 0 || value > max { return Err(format!("security.{name} 须为 1..={max} 的整数")); }
    }
    for (name, value, max) in [
        ("windowSecs", config.rate_limit.window_secs, 3600),
        ("readRequests", config.rate_limit.read_requests, 10000),
        ("writeRequests", config.rate_limit.write_requests, 10000),
        ("loginRequests", config.rate_limit.login_requests, 10000),
        ("globalMultiplier", config.rate_limit.global_multiplier, 10000),
    ] {
        if value == 0 || value > max { return Err(format!("rateLimit.{name} 须为 1..={max} 的整数")); }
    }
    Ok(config)
}

fn csv(raw: &str) -> Vec<String> {
    raw.split(',').map(str::trim).filter(|v| !v.is_empty()).map(String::from).collect()
}

pub fn validate_url(raw: &str) -> Result<(), String> {
    ureq::get(raw).request_url().map_err(|e| format!("互联 URL 非法: {e}"))?;
    let rest = raw.strip_prefix("https://").or_else(|| raw.strip_prefix("http://"))
        .ok_or_else(|| format!("互联 URL 只支持 http/https: {raw}"))?;
    let host = rest.split('/').next().ok_or("互联 URL 缺主机名")?;
    if host.is_empty() || raw.chars().any(char::is_whitespace)
        || raw.contains(['@', '#', '?', '\\'])
    {
        return Err(format!("互联 URL 非法（不允许凭据、查询或片段）: {raw}"));
    }
    Ok(())
}

